import { gsap } from 'gsap';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec2, smoothstep, vec3 } from 'three/tsl';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'quote-panel-pricing';

  const CARD_W = 2.4;
  const CARD_H = 1.5;

  // --- Depth plane 1: accent edge frame (behind card, slightly larger) ---
  const frameGeo = new PlaneGeometry(CARD_W + 0.1, CARD_H + 0.1);
  const frameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.18,
    roughness: 0.6,
    metalness: 0.2,
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.015;
  root.add(frameMesh);

  // --- Depth plane 2: the card face (textured) ---
  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.55,
    metalness: 0.35,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0;
  root.add(cardMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  // --- Depth plane 3: radial contact shadow beneath the card ---
  const shadowRadius = CARD_W * 0.7;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 1.3);
  const shadowDist = uv().sub(vec2(0.5, 0.5)).length();
  const shadowAlpha = smoothstep(0.5, 0.05, shadowDist).mul(0.5);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowAlpha;
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -CARD_H * 0.62, -0.5);
  shadowMesh.rotation.x = 0;
  root.add(shadowMesh);

  // --- Local rim / accent light (scene only supplies ambient + key) ---
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.2, 0.8, 1.5);
  root.add(rimLight);
  root.add(rimLight.target);

  // --- Text content (bridging idiom) — render only if data actually present ---
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let cursorY = CARD_H * 0.32;
  for (const item of items) {
    const isQuote = item.role === 'quote' || item.role === 'body';
    const fontSize = item.typography?.fontSize ?? (isQuote ? 34 : 20);
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: isQuote ? colors.ink : colors.accent,
      align: 'left',
      maxWidthPx: CARD_W * 300,
    });
    txt.position.set(-CARD_W * 0.42, cursorY, 0.01);
    cursorY -= isQuote ? 0.5 : 0.24;
    root.add(txt);
    textNodes.push(txt);
  }

  // --- Cinematic primitives (applied exactly as specified) ---
  const appliedPrimitives = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const handler = ctx.primitives[prim.name];
    if (typeof handler === 'function') {
      appliedPrimitives.push(handler(root, prim.params ?? {}));
    }
  }

  // --- Motion timelines ---
  const baseY = root.position.y || 0;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(root.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(frameMat, { emissiveIntensity: 0.55, duration: 0.3, ease: 'power2.out' }, 0);

  const settleTl = gsap.timeline();
  root.scale.setScalar(0.98);
  settleTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  function onHover() {
    hoverTl.play();
  }
  function onHoverEnd() {
    hoverTl.reverse();
  }
  function onClick() {
    gsap.timeline()
      .to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' })
      .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out(2)' });
    ctx.emit('hub-pricing.select', { nodeId: config.id ?? 'quote-panel' });
  }

  root.userData.handlers = {
    onPointerOver: onHover,
    onPointerEnter: onHover,
    onHover,
    onPointerOut: onHoverEnd,
    onPointerLeave: onHoverEnd,
    onHoverEnd,
    onClick,
    onPointerDown: onClick,
  };

  root.userData.cleanup = () => {
    hoverTl.kill();
    settleTl.kill();
    for (const p of appliedPrimitives) {
      p?.timeline?.kill?.();
      p?.cleanup?.();
    }
    cardGeo.dispose();
    frameGeo.dispose();
    shadowGeo.dispose();
    cardMat.map?.dispose?.();
    cardMat.dispose();
    frameMat.dispose();
    shadowMat.dispose();
    for (const t of textNodes) {
      t.traverse?.((c) => {
        c.geometry?.dispose?.();
        c.material?.dispose?.();
      });
    }
  };

  return root;
}
